  "workflow": { "namespace": "tapd", "id": "1020124" },
  "source": "prd-flow",
  "title": "Issue1 · Android 方案草稿",
  "markdown": "# 方案内容\\n...",
  "stage": "issue-plan:runtime-hook",
  "issueKey": "runtime-hook",
  "platform": "android",
  "artifactKey": "plan:runtime-hook:android",
